```json
{
  "root_causes": [
    {
      "service": "ts-admin-basic-info-service",
      "fault_kind": "application_method_slow",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT 'abn' p, service_name, span_name, attr_span_kind, count(*) n, approx_quantile(duration,0.5)/1e6 p50_ms, approx_quantile(duration,0.95)/1e6 p95_ms FROM abnormal_traces WHERE service_name='ts-admin-basic-info-service' AND span_name LIKE '%getAllContacts%' OR (service_name='ts-admin-basic-info-service' AND span_name LIKE 'GET /api/v1/adminbasicservice/adminbasic/contacts%') GROUP BY 1,2,3,4 UNION ALL SELECT 'norm', service_name, span_name, attr_span_kind, count(*), approx_quantile(duration,0.5)/1e6, approx_quantile(duration,0.95)/1e6 FROM normal_traces WHERE service_name='ts-admin-basic-info-service' AND span_name LIKE '%getAllContacts%' OR (service_name='ts-admin-basic-info-service' AND span_name LIKE 'GET /api/v1/adminbasicservice/adminbasic/contacts%') GROUP BY 1,2,3,4",
          "claim": "getAllContacts internal span and GET /contacts server span rose from about 8-10 ms p95 to about 1,680 ms p50 in abnormal period."
        },
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_span_kind, count(*) n, approx_quantile(duration,0.5)/1e6 p50_ms FROM abnormal_traces WHERE service_name='ts-admin-basic-info-service' AND attr_span_kind='Client' GROUP BY 1,2,3",
          "claim": "Child client calls of the service stay around 4-5 ms p50, so the extra ~1.68 s is inside the method itself."
        },
        {
          "kind": "metric",
          "sql": "SELECT 'abn' p, metric, avg(value) avg_v, max(value) max_v FROM abnormal_metrics WHERE service_name='ts-admin-basic-info-service' AND metric IN ('k8s.pod.cpu.usage','k8s.pod.memory.working_set','k8s.pod.uptime') GROUP BY 1,2 UNION ALL SELECT 'norm', metric, avg(value), max(value) FROM normal_metrics WHERE service_name='ts-admin-basic-info-service' AND metric IN ('k8s.pod.cpu.usage','k8s.pod.memory.working_set','k8s.pod.uptime') GROUP BY 1,2",
          "claim": "Pod CPU and memory are flat or lower in abnormal period; no resource saturation or restart explains the slowdown."
        },
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_span_kind, count(*) n, approx_quantile(duration,0.95)/1e6 p95_ms FROM abnormal_traces WHERE span_name LIKE '%adminbasicservice/adminbasic%' AND attr_span_kind='Server' GROUP BY 1,2,3 ORDER BY 2",
          "claim": "Other adminbasic endpoints (configs, prices, stations, trains) on the same service stay at about 5-9 ms p95; only contacts is slow."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "ts-admin-basic-info-service",
      "to": "ts-ui-dashboard",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_span_kind, count(*) n, approx_quantile(duration,0.5)/1e6 p50_ms FROM abnormal_traces WHERE span_name LIKE '%adminbasicservice/adminbasic/contacts%' GROUP BY 1,2,3 ORDER BY 1,3",
          "claim": "ts-ui-dashboard's contacts server span takes about 1,683 ms p50, matching the slow callee, and the loadgenerator user request shows the same delay."
        }
      ]
    }
  ]
}
```

